  "e": "숫자 -246000을 입력한 후 지문의 표시 형식을 지정하면 -24600이 음수이므로 (#0.0,“천원”) 서식이 적용되어 (246.0천원)으로 표시됩니다. •#0.0,“천원” : 양수일 때 적용되는 서식으로, #0.0,“천원” 형식으로 표시됩니다.  246000 → 246.0천원 ※ #0.0,에서 콤마(,)는 천 단위를 생략할 때 사용합니다. •(#0.0,“천원”) : 음수일 때 적용되는 서식으로, #0.0,“천원” 형식으로 표시하되 음수 표시는 ( )로 나타냅니다.  -246000 → (246.0천원) •0.0 : 0일 때 적용되는 서식으로, 0.0으로 표시됩니다.  0 → 0.0 •@“님” : 텍스트일 때 적용되는 서식으로, 해당 텍스트 다음에 “님”을 표시합니 다.  합격 → 합격님",
