  "e": "매월의 불입 금액을 계산하는 함수식으로 옳은 것은 ①번입니 다. PMT(이자, 기간, 현재 가치, 미래 가치, 납입 시점) 함수를 사용하여 계산하면 다음과 같습니다. •이자 : 이율이 연 단위이므로 12로 나누면 ‘6.5%/12’입니다. •기간 : 기간이 년 단위이므로 년에 12를 곱하면 ‘3*12’입니다. •현재가치 : 대출금을 현재 받았으므로 현재 가치이고, 결과값이 양수로 나오도록 음수로 입력하면 ‘-30000000’입니다. •미래가치 : 0이므로 생략합니다. •납입시점 : 매월 말이므로 생략합니다. ∴ 각 인수를 함수에 대입하면 ‘=PMT(6.5%/12, 3*12, -30000000)’입니다.",
