  "q": "다음 조건을 이용하여 사용자 지정 표시 형식을 설정할 경우 옳은 것은? •양수와 음수 모두에 천 단위 구분 기호 표시 •음수인 경우 음수 기호(-) 없이 빨강색으로 표시 [표시 예] •1500 : 1,500.00 •-2450 : 2,450.00 •50.1 : 50.10 •0 : 0.00",
