  "q": "다음 워크시트에서 [A2:A6] 영역(예: 서울특별시…, 부산광역시…)의 앞에 두 글자를 이용하여 [B2:B6] 영역에 지역을 표시하려고 할 때, [B2] 셀에 “서울”을 입력한 후 눌러야 하는 바로 가기 키는?",
