  "e": "일반 사용자가 인터넷상에서 통신하는 정보를 크래커의 사이트를 통과하도록 하여 비밀번호를 알아내는 방법을 웹 스푸핑(WebSpoofing)이라고 합니다. 보기의 다른 용어의 의미도 알아두세요. •스니퍼(Sniffer) : 통신선상에 전송되고 있는 정보를 상대방이 모르게가로채는 방법 •트랩 도어(Trap Door, Back Door) : 서비스 기술자나 유지·보수 프로그래머들의 액세스 편의를 위해 만든 보안이 제거된 비밀 통로를이르는 말로, 시스템에 무단 접근하기 위한 일종의 비상구 •DOS(Denial Of Service) : 서버의 데이터나 자원을 독점하거나 파괴 하여 다른 사용자들이 서비스를 사용할 수 없도록 하는 모든 행위",
