  "q": "릴레이션 A에는 60개의 튜플이 있고, 다른 릴레이션 B에는 30개의 튜플이 있다. 이 두 개의 릴레이션에 대해 카티젼 곱(Cartesian Product) 연산을 실행한 후의 튜플의 수는 몇 개인가?",
