  "set": "모의 2회",
  "n": 25,
  "s": 2,
  "q": "다음 시트에서 판매1팀 사원들의 근무년수 평균을 구하려고 할 때 수식으로 옳지 않은 것은?",
  "o": [
   "=AVERAGEIF(A2:A7, “판매1팀”, C2:C7)",
   "=AVERAGEIFS(C2:C7, A2:A7, “판매1팀”)",
   "{=AVERAGE((A2:A7=“판매1팀”)*(C2:C7))}",
   "{=AVERAGE(IF(A2:A7=“판매1팀”, C2:C7))}"
  ],
  "a": 3,
  "e": "평균을 구하는 배열 수식은 ④번과 같이 AVERAGE와 IF 함수를 이용하여 조건이 거짓일 때 아무 값도 없는 NULL 값을 반환하여 값을 구해야 합니다. ③번과 같이 AVERAGE 함수만을 이용하여 값을 구할 경우 조건이 거짓일 때 0이 AVERAGE 함수의 인수로 포함되어평균이 계산됩니다. 즉 ④번 보기는 ‘=AVERAGE(15, 7, 7)’로 계산되지만, ③번 보기는 ‘=AVERAGE(15, 0, 7, 0, 0, 7)’로 계산되어 올바른 결과값이 나오지 않습니다. 보기에 제시된 함수의 사용 형식을 알아두세요. •AVERAGE(인수1, 인수2, …) : 인수의 평균값 •AVERAGEIF(조건이 적용될 범위, 조건, 평균을 구할 범위) : 조건에 맞는 셀들의 평균값 •AVERAGEIFS(평균을 구할 범위, 조건1, 조건1이 적용될 범위, 조건2, 조건 2가 적용될 범위, …) : 여러 조건에 맞는 셀들의 평균값",
