  "e": "=INDEX(B2:F6, MATCH(3, A2:A6, 0), MATCH(3.5, B1:F1, 1)) ❶ ❷ ❸ •❶ MATCH(3, A2:A6, 0) : [A2:A6] 영역에서 3과 정확히 일치하는 값을 찾아 상대 위치를 표시하므로 결과값은 3입니다. •❷ MATCH(3.5, B1:F1, 1) : [B1:F1] 영역에서 3.5보다 작거나 같은 값 중에서 가장 근접한 값을 찾아 상대 위치를 표시하므로 결과값은 3 입니다. •❸ =INDEX(B2:F6, ❶, ❷) → =INDEX(B2:F6, 3, 3) : [B2:F6] 영역에서 3행 3열(D4)에 있는 값 260이 표시됩니다. `MATCH(기준값, 범위, 옵션) 옵션 •1 : 기준값보다 작거나 같은 값 중에서 가장 근접한 값을 찾음 •0 : 기준값과 정확히 일치하는 값을 찾음 •－1 : 기준값보다 크거나 같은 값 중에서 가장 근접한 값을 찾음",
