  "q": "아래의 시트에서 단가가 500,000 이상이면서 주문량이 150 이상인제품의 수를 계산하는 배열 수식으로 옳은 것은?",
  "o": [
   "{=COUNT((B2:B8>=500000)*(C2:C8>=150))}",
   "={COUNT((B2:B8>=500000)*(C2:C8>=150))}",
   "={COUNT(IF((B2:B8>=500000)*(C2:C8>=150), 1, “ ”))}",
   "{=COUNT(IF((B2:B8>=500000)*(C2:C8>=150), 1, “ ”))}"
  ],
  "a": 4,
  "e": "항상 개수를 구하는 방법은 다음의 3가지 방법이 있으며, 조건의 개수에 따라 조건을 지정하는 부분만 늘어납니다. 이 문제에서는 조건 이 두 개이므로 조건이 두 개일때의 조건 지정 방법을 알아보겠습니다. •방법1 : {=SUM( (조건1)*(조건2) )} •방법2 : {=SUM( IF(조건1, IF(조건2,1) ) )} •방법3 : {=COUNT( IF( (조건1)*(조건2), 1) )} 1. 조건과 범위 찾기 •조건1 : 단가가 500,000 이상이란 조건은, 비교 대상이 될 단가가 있는 범위와 비교할 기준이 되는 500,000을 “>=”으로 연결하여 입력하면 됩니다(B2:B8>=500000). •조건2 : 주문량이 150 이상이란 조건은, 비교 대상이 될 주문량이 있는 범위와 비교할 기준이 되는 150을 “>=”로 연결하여 입력하면 됩니다(C2:C8>=150). 실전 모의고사 정답 및 해설 2. 위의 조건을 개수 구하기 배열 수식에 대입하면 다음과 같습니다. •방법1 : =SUM((B2:B8>=500000)*(C2:C8>=150)) •방법2 : =SUM(IF(B2:B8>=500000, IF(C2:C8>=150, 1))) •방법3 : =COUNT(IF((B2:B8>=500000)*(C2:C8>=150), 1)) COUNT는 인수 중 숫자가 들어 있는 셀의 개수를 구하는 함수로 방법3을 =COUNT(IF((B2:B8>=500000)*(C2:C8 >=150), 1, “”))으로 입력해도 결과값은 동일합니다. ※ 수식을 입력한 후 Ctrl + Shift + Enter를 누르면 중괄호 { }가 표시되어 {=COUNT(IF((B2:B8>=500000)*(C2:C8>=150), 1, “”))}로 표시됩니다.",
  "img": "q/M5-26",
  "eimg": "e/M5-26",
  "sec": 83,
  "tip": [
   83,
   33
  ]
